def count_max_preemptions(task_i, hp_tasks, window_w):
    total_preemptions = 0
    for task_j in hp_tasks:
        total_preemptions += math.ceil(window_w / task_j.T_j)
    return total_preemptions

def calculate_crta_response_time(task_i, hp_tasks, gamma_map):
    w_i = task_i.C_i + task_i.B_i
    while True:
        interference = 0
        for task_j in hp_tasks:
            num_releases = math.ceil(w_i / task_j.T_j)
            # Add both execution time and cache refill penalty
            interference += num_releases * (task_j.C_j + gamma_map[task_j])

        new_w = task_i.C_i + task_i.B_i + interference

        if new_w == w_i:
            return new_w
        if new_w > task_i.D_i:
            return float('inf') # Not schedulable
        w_i = new_w
